<?php $e=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};?><!doctype html><html><head><meta charset="utf-8"><?php include('includes/page-title.php');?><link href="<?=base_url()?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?=base_url()?>assets/css/app.min.css" rel="stylesheet"></head><body><div id="wrapper"><?php include('includes/top-bar.php');include('includes/sidebar.php');?><div class="content-page"><div class="content"><div class="container-fluid"><div class="card mt-4"><div class="card-body"><a class="btn btn-primary float-right" href="<?=base_url()?>Page/iso_qms_add/<?=$module['key']?>">Add Record</a><small>ISO 9001:2015 · <?=$e($sectionName)?></small><h3><?=$e($module['label'])?></h3><?php if($this->session->flashdata('success')):?><div class="alert alert-success"><?=$e($this->session->flashdata('success'))?></div><?php endif;?><div class="table-responsive"><table class="table"><tr><th>Date</th><th>Reference</th><th>Title / Subject</th><th>Owner</th><th>Status</th><th>Due Date</th><th></th></tr><?php foreach($records as $r):?><tr><td><?=$e($r->record_date)?></td><td><?=$e($r->reference_no)?></td><td><b><?=$e($r->title)?></b><br><small><?=$e($r->details)?></small></td><td><?=$e($r->owner)?></td><td><?=$e($r->status)?></td><td><?=$e($r->due_date)?></td><td><a class="text-danger" onclick="return confirm('Delete this record?')" href="<?=base_url()?>Page/iso_qms_delete/<?=$module['key']?>/<?=$r->id?>">Delete</a></td></tr><?php endforeach;?></table></div></div></div></div></div><?php include('includes/footer.php');?></div></div></body></html>
